        filepath = os.path.join(root, f)
        with open(filepath) as fh:
            lines = fh.readlines()

        in_test = False
        brace_depth = 0
        test_brace_start = 0

        for i, line in enumerate(lines, 1):
            stripped = line.strip()

            # Track test module
            if '#[cfg(test)]' in stripped:
                in_test = True
                test_brace_start = 0
